// price is 1-indexed: price[c] is the value of a length-c piece
private int best(int[] price, int rem) {
    if (rem == 0) {
        return 0;
    }
    int top = 0;
    for (int c = 1; c <= rem; c++) {
        top = Math.max(top, price[c] + best(price, rem - c));
    }
    return top;
}

