public int rodCutting(int[] price, int n) {
    int[] memo = new int[n + 1];
    Arrays.fill(memo, -1);
    return best(price, n, memo);
}

private int best(int[] price, int rem, int[] memo) {
    if (rem == 0) {
        return 0;
    }
    if (memo[rem] != -1) {
        return memo[rem];
    }
    int top = 0;
    for (int c = 1; c <= rem; c++) {
        top = Math.max(top, price[c] + best(price, rem - c, memo));
    }
    memo[rem] = top;
    return top;
}

