public int rodCutting(int[] price, int n) {
    int[] dp = new int[n + 1];
    for (int len = 1; len <= n; len++) {
        for (int c = 1; c <= len; c++) {
            dp[len] = Math.max(dp[len], price[c] + dp[len - c]);
        }
    }
    return dp[n];
}

