def rod_cutting(self, price: list[int], n: int) -> int:
    dp = [0] * (n + 1)
    for length in range(1, n + 1):
        for c in range(1, length + 1):
            dp[length] = max(dp[length], price[c] + dp[length - c])
    return dp[n]

